-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_VITREA_TEASER.SNOWBOTS.T_CLOSE_SENTINEL
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Berlin'
  CONFIG = '{"autonomy": 3}'
  WHEN SYSTEM$STREAM_HAS_DATA('SDP_VITREA_TEASER.PUBLIC.STR_GL_JOURNAL')
AS
  CALL SDP_VITREA_TEASER.SNOWBOTS.SP_RUN_BOT('close-sentinel');

-- step 1 · Actuals landed: October GL + KIS census
SELECT SYSTEM$STREAM_HAS_DATA('SDP_VITREA_TEASER.PUBLIC.STR_GL_JOURNAL') OR SYSTEM$STREAM_HAS_DATA('SDP_VITREA_TEASER.PUBLIC.STR_KIS_CENSUS');
-- step 2 · Completeness DMFs per feed
SELECT feed, SNOWFLAKE.CORE.ROW_COUNT(...) AS rows_loaded, expected_rows,
       rows_loaded / expected_rows AS completeness
FROM SDP_VITREA_TEASER.SNOWBOTS.V_FEED_EXPECTATIONS WHERE period = '2026-10';
-- step 3 · Fallback: rebuild census from HL7 ADT archive
CALL SDP_VITREA_TEASER.SNOWBOTS.SP_BACKFILL_CENSUS_FROM_ADT('KIS', '2026-10', clinics => 'MISSING');
-- step 4 · Reconcile: care days × daily rate vs payer billing
CALL SDP_VITREA_TEASER.SNOWBOTS.SP_RECONCILE(period => '2026-10', tolerance_pct => 0.5);
-- step 5 · Guardrail: completeness ≥ 98% and billing difference = 0
SELECT MIN(completeness) >= 0.98 AND ABS(SUM(billing_diff)) = 0 FROM SDP_VITREA_TEASER.SNOWBOTS.V_CLOSE_STATUS WHERE period = '2026-10';
-- step 6 · Lock period 2026-10 (awaiting CFO approval)
CALL SDP_VITREA_TEASER.PUBLIC.SP_LOCK_PERIOD('2026-10', approved_by => :approver);

