-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_VITREA_TEASER.SNOWBOTS.T_DRIVER_REFRESH
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Berlin'
  CONFIG = '{"autonomy": 4}'
AS
  CALL SDP_VITREA_TEASER.SNOWBOTS.SP_RUN_BOT('driver-refresh');

-- step 1 · Marketplace share refreshed
SELECT MAX(date) FROM FX_MARKETPLACE.PUBLIC.FX_RATES_DAILY;
-- step 2 · Upsert FX and energy drivers
MERGE INTO SDP_VITREA_TEASER.PUBLIC.DIM_FX_RATE t USING (SELECT * FROM FX_MARKETPLACE.PUBLIC.FX_RATES_DAILY WHERE date = CURRENT_DATE) s ON t.pair = s.pair ...;
-- step 3 · Guardrail: daily move ≤ 3%
SELECT MAX(ABS(pct_change)) <= 0.03 FROM SDP_VITREA_TEASER.SNOWBOTS.V_FX_MOVES;
-- step 4 · Recalculate Swiss revenue + energy cost for Nov–Dec
CALL SDP_VITREA_TEASER.PUBLIC.SP_RECALC(scope => 'REVENUE_CH,ENERGY', from_period => '2026-11');
-- step 5 · One-line impact note
SELECT AI_COMPLETE('claude-sonnet-4-5', 'One sentence on: ' || :impact_json);

