-- Deployable spec (not executed in demo mode)
CREATE OR REPLACE TASK SDP_VITREA_TEASER.SNOWBOTS.T_SPEND_GUARDIAN
  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Berlin'
  CONFIG = '{"autonomy": 1}'
AS
  CALL SDP_VITREA_TEASER.SNOWBOTS.SP_RUN_BOT('spend-guardian');

-- step 1 · Renewals due ≤ 90 days
SELECT * FROM SDP_VITREA_TEASER.PUBLIC.DIM_CONTRACT WHERE renewal_date <= DATEADD(day, 90, CURRENT_DATE);
-- step 2 · Compare unit price vs benchmark
SELECT c.vendor, c.unit_price / b.p50 - 1 AS premium FROM ... JOIN SDP_VITREA_TEASER.SNOWBOTS.V_VENDOR_BENCHMARK b ...;
-- step 3 · Recommendations to Procurement
INSERT INTO SDP_VITREA_TEASER.PUBLIC.NOTIFICATIONS ...;

