  WAREHOUSE = SDP_BOT_WH
  SCHEDULE = 'USING CRON 0 6 * * * Europe/Berlin'
  CONFIG = '{"autonomy": 2}'
AS
  CALL SDP_VITREA_TEASER.SNOWBOTS.SP_RUN_BOT('hc-reconciler');

-- step 1 · Payroll vs plan by facility type and staff group
SELECT facility_type, staff_group, payroll_fte, plan_fte FROM SDP_VITREA_TEASER.SNOWBOTS.V_HC_RECON WHERE period = '2026-10';
